using UnityEngine;using UnityEditor;using LWS.TruckSports.Editor;
namespace LWS.TruckTugOfWar.Editor {public static class TugProductionAuthoring {
 public static void Install(TugMatch m){var existing=GameObject.Find("Volcanic depth and textured lava presentation");var root=existing!=null?existing.transform:new GameObject("Volcanic depth and textured lava presentation").transform;var pool=GameObject.Find("Lava far below the mountain");if(pool==null)throw new System.Exception("Actual saved lava pool required");var mat=pool.GetComponent<Renderer>().sharedMaterial;mat.shader=Shader.Find("LWS/TruckSports/Volcanic Lava Flow");if(mat.shader==null)throw new System.Exception("Owned lava flow shader required");mat.SetColor("_BaseColor",new Color(.055f,.012f,.008f));mat.SetColor("_EmissionColor",new Color(3.2f,.45f,.015f));mat.SetFloat("_FlowSpeed",.16f);mat.SetFloat("_Surface",1);EditorUtility.SetDirty(mat);if(existing==null)for(int i=0;i<14;i++){float a=i*Mathf.PI*2/14;var p=new Vector3(Mathf.Sin(a)*85,-72,Mathf.Cos(a)*67);LWS.TruckBaseJumping.Editor.BaseSkyAuthoring.Scenery(root,p,48+i%4*9,false,"TruckTugOfWar");}foreach(Transform child in root){if(child.GetComponentsInChildren<Collider>(true).Length!=0)throw new System.Exception("Only nonphysical distant rocks may be fitted");bool first=true;Bounds bounds=default;foreach(var renderer in child.GetComponentsInChildren<Renderer>(true)){if(first){bounds=renderer.bounds;first=false;}else bounds.Encapsulate(renderer.bounds);}var scale=child.localScale;scale.x*=Mathf.Min(1,32/Mathf.Max(.01f,bounds.size.x));scale.z*=Mathf.Min(1,28/Mathf.Max(.01f,bounds.size.z));child.localScale=scale;}EditorUtility.SetDirty(m);}
}}
